fn align_to_stride(value: u64, stride: u64) -> u64 {
    let stride = stride.max(1);
    if value == u64::MAX {
        return value;
    }
    let remainder = value % stride;
    if remainder == 0 {
        value
    } else {
        value.saturating_add(stride - remainder)
    }
}
```

