```rust
// crates/gossip-coordination-etcd/src/test_etcd.rs (or tests/common/mod.rs)

use testcontainers::{GenericImage, ImageExt, Container, core::WaitFor, runners::SyncRunner};
use std::sync::OnceLock;

/// etcd container image configuration.
/// Uses bitnami/etcd with authentication disabled for testing.
fn etcd_image() -> GenericImage {
    GenericImage::new("bitnami/etcd", "3.5")
        .with_exposed_port(2379.tcp())
        .with_env_var("ALLOW_NONE_AUTHENTICATION", "yes")
        .with_env_var("ETCD_ADVERTISE_CLIENT_URLS", "http://0.0.0.0:2379")
        .with_env_var("ETCD_LISTEN_CLIENT_URLS", "http://0.0.0.0:2379")
        .with_wait_for(WaitFor::message_on_stderr("ready to serve client requests"))
}

/// Shared container for the test binary. Started lazily on first use.
/// Each test gets its own EtcdCoordinator with a unique namespace prefix.
static ETCD_CONTAINER: OnceLock<EtcdEndpoint> = OnceLock::new();

struct EtcdEndpoint {
    host: String,
    port: u16,
    // Container handle kept alive to prevent cleanup
    _container: Container<GenericImage>,
}

/// Returns a fresh EtcdCoordinator connected to the shared test etcd,
/// using a unique namespace prefix for test isolation.
pub fn test_etcd_coordinator(test_name: &str) -> EtcdCoordinator {
    let ep = ETCD_CONTAINER.get_or_init(|| {
        let container = etcd_image().start().expect("failed to start etcd container");
        let host = container.get_host().expect("failed to get host");
        let port = container.get_host_port_ipv4(2379).expect("failed to get port");
        // All container metadata extracted here, before any EtcdCoordinator is created.
        // This ensures the SyncRunner's temporary Tokio runtime is fully dropped.
        EtcdEndpoint { host: host.to_string(), port, _container: container }
    });

    let endpoint = format!("http://{}:{}", ep.host, ep.port);
    // UUID-based namespace prefix for per-test isolation
    let namespace = format!("/test/{}/{}", test_name, uuid::Uuid::new_v4());
    let config = EtcdCoordinatorConfig::from_endpoints_csv(&endpoint, &namespace)
        .expect("test config should be valid");
    EtcdCoordinator::connect(config).expect("test etcd should be reachable")
}
```

### 3. Critical runtime sequencing

The call sequence MUST be:
1. `SyncRunner::start()` — creates temporary Tokio runtime, drops it on return
2. `Container::get_host()` / `get_host_port_ipv4()` — may create temporary runtime
3. Extract host and port as owned values
4. **Only then** call `EtcdCoordinator::connect()` — creates its own runtime

If steps 1-3 and step 4 overlap on the same thread with an active Tokio runtime, `EtcdCoordinator::connect()` will panic (debug) or misbehave (release) due to the nested `block_on()`.

