// crates/gossip-coordination/src/conformance.rs (new)
//! Backend-agnostic coordination conformance harness.

use crate::sim::backend::SimulationBackend;
use gossip_contracts::coordination::shard_spec::CursorSemantics;

/// Runs the coordination conformance suite against any backend.
///
/// The factory creates a fresh, seeded backend for each test.
/// Most tests use `CursorSemantics::Completed`; one test passes
/// `CursorSemantics::Dispatched` to verify dispatch routing.
pub fn run_coordination_conformance<B, F>(factory: F)
where
    B: SimulationBackend,
    F: Fn(CursorSemantics) -> B,
{
    // fence_monotonicity_across_full_lifecycle
    {
        eprintln!("  conformance: fence_monotonicity_across_full_lifecycle");
        let mut coord = factory(CursorSemantics::Completed);
        // ... test body, using coord.shard_lookup() and
        // coord.cursor_last_key() instead of coord.slab()
    }
    // ... all 16 test function bodies
    // For run_terminal_irreversibility, expand rstest into 2 blocks:
    {
        eprintln!("  conformance: run_terminal_irreversibility [Done]");
        let expected_status = RunStatus::Done;
        let mut coord = factory(CursorSemantics::Completed);
        // ... body
    }
    {
        eprintln!("  conformance: run_terminal_irreversibility [Cancelled]");
        let expected_status = RunStatus::Cancelled;
        let mut coord = factory(CursorSemantics::Completed);
        // ... body
    }
}
```

### Replace slab() with SimIntrospection methods

All 16 direct `coord.slab()` calls become:
- `rec.cursor.last_key(coord.slab())` → `coord.cursor_last_key(&rec)`
- `rec.spec.key_range_start(coord.slab())` → `coord.spec_bounds(&rec).0`
- `rec.spec.key_range_end(coord.slab())` → `coord.spec_bounds(&rec).1`

Additionally, the `split_coverage_key_range_partition` test at line 611 saves `coord.slab()` to a local variable (`let slab = coord.slab()`) with 6 downstream usages. These must also be converted — use destructuring for clarity:

```rust
let (a_start, a_end) = coord.spec_bounds(rec_a);
let (b_start, b_end) = coord.spec_bounds(rec_b);
assert_eq!(a_end, b_start); // contiguity
```

### Inline conformance_tests.rs calls the harness

```rust
