`scanner-git` already defines the canonical explicit-ref normalization rule we should mirror in the request model: explicit refs are order-invariant and duplicate-invariant.

```rust
// crates/scanner-git/src/start_set.rs:108-156 — explicit refs sort and dedupe before canonical encoding
pub(crate) fn encode_canonical(&self, out: &mut Vec<u8>) {
    out.clear();
    out.extend_from_slice(b"start_set");
    out.push(0);
    out.push(Self::VERSION);

    match self {
        StartSetConfig::ExplicitRefs { refs } => {
            out.push(4);
            let mut v: Vec<&[u8]> = refs.iter().map(|r| r.as_slice()).collect();
            v.sort_unstable();
            v.dedup();
            push_u32_le(out, v.len() as u32);
            for r in v {
                push_bytes_u16(out, r);
            }
        }
```

