The filesystem setup helper is the direct template for the coordinator-facing part of this task: validate preconditions before mutation, build a manifest through `PreallocShardBuilder`, then delegate to `create_run_with_shards`.

```rust
// crates/gossip-orchestrator/src/setup.rs:256-303 — setup helper lowers typed inputs into a manifest and registers the run
pub fn setup_filesystem_run<M>(
    management: &mut M,
    now: LogicalTime,
    tenant: TenantId,
    run: RunId,
    input: FilesystemRunSetupInput<'_>,
    op_id: OpId,
) -> Result<IdempotentOutcome<FilesystemRunSetupResult>, FilesystemRunSetupError>
where
    M: RunManagement,
{
    let request = input.request();
    let geometry = input.geometry();
    let payload = input.payload();
    validate_request_payload(request, payload)?;

    let encoded_payload = payload.encode()?;
    let (start, end) = lower_geometry_bounds(&geometry);
    let mut arena = ShardArena::with_capacity(1, byte_capacity);
    let mut builder = PreallocShardBuilder::<1>::new(&mut arena, 1)?;
    let _ = builder.add_range(start, end, &encoded_payload)?;
    let manifest = builder.build_inputs()?;

    let outcome = management.create_run_with_shards(
        now,
        tenant,
        run,
        request.run_config(),
        manifest.as_slice(),
        op_id,
    )?;
```

The coordinator lifecycle we need to reuse is already defined and already documents the replay semantics this task must preserve.

```rust
// crates/gossip-coordination/src/run.rs:1600-1637 — default retry-friendly create+register helper
fn create_run_with_shards(
    &mut self,
    now: LogicalTime,
    tenant: TenantId,
    run: RunId,
    config: RunConfig,
    shards: &[InitialShardInput<'_>],
    op_id: OpId,
) -> Result<IdempotentOutcome<RunRecord>, CreateRunError> {
    match self.create_run(now, tenant, run, config) {
        Ok(_) => {}
        Err(CreateRunError::RunAlreadyExists { .. }) => {
            let existing = self.get_run(tenant, run)?;
            if existing.config != config {
                return Err(CreateRunError::ConfigMismatch { run });
            }
        }
        Err(e) => return Err(e),
    }

    let outcome = self.register_shards(now, tenant, run, shards, op_id)?;
    let record = self.get_run(tenant, run)?;
    Ok(outcome.map(|_| record))
}
```

