// crates/gossip-worker/src/recorder.rs:651-677 — Git event sanitization already redacts OIDs and identity values
fn from_git_event(shard_id: &str, event: StoredGitEvent) -> Self {
    let shard_id = RedactedDigest::text("shard_id", shard_id);
    match event {
        StoredGitEvent::CommitMeta {
            commit_id, oid_hex, timestamp,
            author_name_id, author_email_id,
            committer_name_id, committer_email_id,
        } => Self::GitCommitMeta {
            shard_id, commit_id,
            oid: RedactedDigest::text("git_commit_oid", &oid_hex),
            timestamp, author_name_id, author_email_id,
            committer_name_id, committer_email_id,
        },
        StoredGitEvent::IdentityDictionary { id, value } => Self::GitIdentityDictionary {
            shard_id, identity_id: id,
            value: RedactedDigest::bytes("git_identity_value", &value),
        },
    }
}
