```rust
/// In-memory Bloom filter for done-ledger prefiltering.
///
/// Wraps `fastbloom::BloomFilter` to accept `OvidHash` keys directly,
/// leveraging the BLAKE3 output's uniform distribution via a pass-through
/// hasher. Gated by cardinality thresholds: returns `None` from `new()`
/// when the expected item count is below the skip threshold or when the
/// resulting filter would exceed the memory cap.
///
/// Construction is a COLD-tier operation (single heap allocation).
/// `maybe_contains()` and `insert()` are allocation-free.
pub(crate) struct DoneLedgerBloomFilter {
    inner: fastbloom::BloomFilter,
    item_count: usize,
}

impl DoneLedgerBloomFilter {
    /// Minimum item count to justify filter construction. Below this
    /// threshold, the filter's memory and construction cost exceed the
    /// savings from avoided database round-trips.
    const MIN_THRESHOLD: usize = 10_000;

    /// Maximum filter memory in bytes. Filters exceeding this cap
    /// degrade to random-access patterns that cause L3 cache misses,
    /// negating the database-avoidance benefit.
    const MAX_BYTES: usize = 32 * 1024 * 1024; // 32 MB

    /// Target false positive rate. 1% is the universal production
    /// standard (RocksDB, Cassandra, CockroachDB, HBase) at ~10 bits/key.
    const TARGET_FPR: f64 = 0.01;

    /// Construct a filter sized for `expected_items`.
    ///
    /// Returns `None` if `expected_items < MIN_THRESHOLD` or if the
    /// memory footprint would exceed `MAX_BYTES`.
    pub(crate) fn new(expected_items: usize) -> Option<Self> { .. }

    /// Check if a hash is *possibly* in the filter.
    ///
    /// Returns `false` only if the hash is definitely NOT in the set.
    /// Returns `true` if the hash *might* be in the set (with <=1% FPR).
    /// Allocation-free.
    #[inline]
    pub(crate) fn maybe_contains(&self, hash: &OvidHash) -> bool { .. }

    /// Insert a hash into the filter. Allocation-free.
    #[inline]
    pub(crate) fn insert(&mut self, hash: &OvidHash) { .. }

    /// Number of items inserted so far.
    pub(crate) fn item_count(&self) -> usize { .. }

    /// Approximate heap memory in bytes.
    pub(crate) fn memory_bytes(&self) -> usize { .. }
}
```

The pass-through hasher extracts `u64` values directly from OvidHash's BLAKE3 bytes rather than re-hashing through SipHash. BLAKE3 output is indistinguishable from uniform random for practical purposes.

