### Ordering Invariant — Recommended Approach

Process each chunk linearly with a `batch_idx` counter:

```rust
// Build reduced batch for DB
let mut positive_hashes = Vec::new();
let mut is_positive = Vec::with_capacity(chunk.len()); // bool per item
for hash in &ovid_hashes {
    let pos = bloom.map_or(true, |b| b.maybe_contains(hash));
    is_positive.push(pos);
    if pos { positive_hashes.push(*hash); }
}

// Call batch_get only on positives (skip if empty)
let batch = if positive_hashes.is_empty() {
    Vec::new()
} else {
    done_ledger.batch_get(tenant_id, policy_hash, &positive_hashes)?
};

// Walk in original order
let mut batch_idx = 0;
classified.extend(chunk.into_iter().zip(is_positive).map(|(item, pos)| {
    let disposition = if pos {
        let d = classify_record(batch[batch_idx]);
        batch_idx += 1;
        d
    } else {
        OrderedContentPrefilterDisposition::ScanMiss
    };
    OrderedContentClassifiedItem::new(item, disposition)
}));
```

