#[test]
fn crc_rejects_corrupted_prefix_blob() {
    let fp = artifact(42);
    let (base_blob, ..) = encode_spill_dedup_base(&fp);

    // Build a valid prefix (PackPlanComplete stage, 0 completed plans).
    let prefix = StoredPrefixState {
        stage: ScanCheckpointStage::PackPlanComplete,
        completed_plan_count: 0,
        scanned: StoredScannedBlobs {
            blobs: Vec::new(),
            finding_arena: Vec::new(),
        },
        skipped_candidates: Vec::new(),
        common_metrics: StoredGitScanCommonMetrics::from(GitScanCommonMetrics::default()),
    };
    let prefix_payload = postcard::to_allocvec(&prefix).expect("encode prefix");
    let mut prefix_blob = wrap_envelope(&prefix_payload);

    // Corrupt a byte inside the payload region (past the 8-byte header).
    let corrupt_idx = ENVELOPE_HEADER_LEN + prefix_payload.len() / 2;
    prefix_blob[corrupt_idx] ^= 0xFF;

    let loaded = LoadedScanCheckpoint::BaseAndPrefix {
        base_state: base_blob,
        prefix_state: prefix_blob,
    };
    // Prefix CRC failure falls back to base-only resume (PostSpillDedup).
    let result = ScanResumeState::from_loaded(loaded, GitScanMode::DiffHistory, &fp)
        .expect("graceful prefix failure returns Ok");
    assert!(
        matches!(result, Some(ScanResumeState::PostSpillDedup(_))),
        "corrupted prefix CRC must fall back to base-only: got {result:?}"
    );
}
```

