```rust
// crates/scanner-engine/src/lsm/set_associative_cache_tests.rs:539-578
// Interleaved get/upsert with reference HashSet — same structure to port.
fn get_upsert_interleaved_prop(
    ops in prop::collection::vec(
        prop_oneof![
            (Just(true), 0u64..500),   // get
            (Just(false), 0u64..500),  // upsert
        ],
        100..500
    )
) {
    let mut cache = ...;
    let mut reference = std::collections::HashSet::<u64>::new();
    for (is_get, key) in ops {
        if is_get {
            if let Some(ptr) = cache.get(key) {
                let value = unsafe { *ptr };
                prop_assert_eq!(key, value);
            }
        } else {
            cache.upsert(&key);
            reference.insert(key);
            let ptr = cache.get(key);
            prop_assert!(ptr.is_some());
        }
    }
}
```

Adapt this for `PackCache`:
- Replace `HashSet` with `HashMap<u64, (ObjectKind, Vec<u8>)>` since
  PackCache stores typed bytes, not identity values.
- Generate `ObjectKind` variants uniformly (4 variants).
- Generate byte payloads with `prop::collection::vec(any::<u8>(), 1..max_size)`.
- Use `PackCache::new_with_policy_for_test` (line 696) to control eviction
  policy deterministically.

