fn validate_fanout(oidf: &[u8]) -> Result<u32, MidxError> {
    let mut prev = 0u32;
    for i in 0..FANOUT_ENTRIES {
        let off = i * 4;
        let val = u32::from_be_bytes([oidf[off], oidf[off + 1], oidf[off + 2], oidf[off + 3]]);
        if val < prev {
            return Err(MidxError::corrupt("fanout not monotonic"));
        }
        prev = val;
    }
    Ok(prev)
}
